'use strict';const test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');
test('V11 production observer contains every canonical custody join',()=>{const source=fs.readFileSync(require.resolve('./secureshopMailAgentReadRenderedProduction'),'utf8');for(const token of ['assessment_judgments','assessment_contributions','assessment_completions','active_assessment_contributions','result_serialized','result_digest','assertRetainedPacket','readConfiguredJudgeProvenance','prepareJudgeInput','requestSha256','responseSha256','merchant.mail_detail'])assert.equal(source.includes(token),true,token);assert.equal(source.includes('mocked:true'),false);assert.equal(source.includes('fallback:true'),false);const raw=source.slice(source.indexOf('const contribution='),source.indexOf('const completion='));assert.doesNotMatch(raw,/c\.(?:objective_id|generation)/);assert.match(raw,/assessment_contributions c JOIN secureshop_auth\.assessment_judgments j/);});

const{randomUUID,createHash}=require('node:crypto');
const{createV11EvidenceObserver}=require('./secureshopMailAgentReadRenderedProduction');
const digest=value=>createHash('sha256').update(value).digest('hex');
function wire(content,format={type:'object'}){const response=JSON.stringify({model:'llama3.1:8b',message:{role:'assistant',content},done:true,done_reason:'stop'})+'\n',request=JSON.stringify({model:'llama3.1:8b',format});return{kind:'actor',model:'llama3.1:8b',status:200,terminalReason:'end',responseComplete:true,responseCaptureTruncated:false,error:null,request,response,requestBytes:Buffer.byteLength(request),responseBytes:Buffer.byteLength(response),responseObservedBytes:Buffer.byteLength(response),responseChunkCount:1,requestSha256:digest(request),responseSha256:digest(response)};}
test('original binds exact physical selection and final wires to saved V11 turn',async()=>{const prior=process.env.OLLAMA_MODEL;process.env.OLLAMA_MODEL='llama3.1:8b';try{const sessionId=randomUUID(),requestId=randomUUID(),choiceId=randomUUID(),saved={status:'completed',text:'Saved final answer',hops:[{tool:'merchant.mail_detail'}],mailRead:{choiceId,result:{kind:'detail',message:{bodyMarkdown:'foreign body'}}}};const selected=wire(JSON.stringify({tool_calls:[{agent:'merchant',tool:'mail_detail',args:{choiceId}}]})),final=wire(JSON.stringify({answer:saved.text}),require(require('node:path').join(process.cwd(),'server/agent-runtime/providers/finalResponseContract')).FINAL_RESPONSE_SCHEMA);const observer=createV11EvidenceObserver({pools:{IDENTITY_RUNTIME:{query(){throw Error('not used')}}},scope:{platformOwnerId:1,platformSessionId:2},persona:{},personaSession:{},principal:{tenantId:randomUUID(),principalId:randomUUID()},assessment:{assertRetainedPacket(){}},runtime:{readRequest:async()=>saved},transport:{calls:[selected,final]},judgeResults:new Map(),capture:{transcripts:[]}});const value=await observer.original({detail:{body:{sessionId,requestId}}});assert.equal(value.actor.decision.tool_calls[0].args.choiceId,choiceId);assert.equal(value.actor.answer.answer,saved.text);const bad=createV11EvidenceObserver({pools:{IDENTITY_RUNTIME:{query(){throw Error('not used')}}},scope:{platformOwnerId:1,platformSessionId:2},persona:{},personaSession:{},principal:{tenantId:randomUUID(),principalId:randomUUID()},assessment:{assertRetainedPacket(){}},runtime:{readRequest:async()=>saved},transport:{calls:[wire(JSON.stringify({tool_calls:[{agent:'merchant',tool:'mail_detail',args:{choiceId:randomUUID()}}]})),final]},judgeResults:new Map(),capture:{transcripts:[]}});await assert.rejects(()=>bad.original({detail:{body:{sessionId,requestId}}}));}finally{if(prior===undefined)delete process.env.OLLAMA_MODEL;else process.env.OLLAMA_MODEL=prior;}});

test('strict V11 wire accepts omitted success error but rejects error and malformed terminal streams',()=>{
 const previous=process.env.OLLAMA_MODEL;process.env.OLLAMA_MODEL='llama3.1:8b';
 try{const H=require('./secureshopMailAgentReadRenderedProduction'),valid=wire(JSON.stringify({answer:'ok'}));delete valid.error;assert.equal(H.readV11WireText(valid,'actor'),JSON.stringify({answer:'ok'}));assert.throws(()=>H.readV11WireText({...valid,error:'upstream failed'},'actor'));assert.throws(()=>H.readV11WireText({...valid,responseComplete:false},'actor'));const malformed={...valid,response:JSON.stringify({model:'llama3.1:8b',message:{role:'assistant',content:'x'},done:false})+'\n'};malformed.responseBytes=Buffer.byteLength(malformed.response);malformed.responseObservedBytes=malformed.responseBytes;malformed.responseSha256=digest(malformed.response);assert.throws(()=>H.readV11WireText(malformed,'actor'));}finally{if(previous===undefined)delete process.env.OLLAMA_MODEL;else process.env.OLLAMA_MODEL=previous;}
});
test('canonical Judge wire join accepts omitted success error and rejects an actual error',()=>{
 const previous=process.env.OLLAMA_MODEL;process.env.OLLAMA_MODEL='llama3.1:8b';
 try{const H=require('./secureshopMailAgentReadRenderedProduction'),physical=wire('{"verdict":"pass"}',{type:'object'});physical.kind='judge';delete physical.error;physical.request=JSON.stringify({model:'llama3.1:8b',messages:[{role:'user',content:'bounded'}],format:{type:'object'}});physical.requestBytes=Buffer.byteLength(physical.request);physical.requestSha256=digest(physical.request);const text=H.readV11WireText(physical,'judge'),proof={requestSha256:digest(JSON.stringify({method:'chat',input:[{role:'user',content:'bounded'}],schema:{type:'object'}})),responseSha256:digest(text)};assert.equal(H.assertV11JudgeWire(physical,proof).text,text);assert.throws(()=>H.assertV11JudgeWire({...physical,error:'judge transport failed'},proof));}finally{if(previous===undefined)delete process.env.OLLAMA_MODEL;else process.env.OLLAMA_MODEL=previous;}
});
